// no chunks, so neither belongs in it.
const NETWORK_CALL = 'fetch(';
const PRELOAD_POLYFILL = 'relList';

test('the built page carries no fetch call or module preload code', async () => {
  const html = await readFile(new URL(GAME_URL), 'utf8');
  assert.equal(html.includes(NETWORK_CALL), false, 'T10 the built page has no fetch call');
  assert.equal(html.includes(PRELOAD_POLYFILL), false, 'T10 the built page has no preload code');
});
import { readFile, writeFile } from 'node:fs/promises';
import { expect, Scrollbars, test, TestTimeouts } from './browser-test.ts';
import { EXAMPLE_PAIRS } from '../src/game/game.fixture.ts';
import { accessibilityTree, accessibilityNode, moveKeyboardTo } from './accessibility-tree.ts';
import { accessibilityFixture, playwrightVersion } from './accessibility-fixture.ts';
import { loadTimedBoard } from './game-fixture.ts';

test('a complete keyboard journey exposes names, states and each result in Chromium accessibility trees', async ({
  page,
  context,
  browser,
}, artifacts) => {
  const expected = await accessibilityFixture();
  await loadTimedBoard(page);
  const session = await context.newCDPSession(page);
  await session.send('Accessibility.enable');
  const captures: { stage: string; tree: Awaited<ReturnType<typeof accessibilityTree>> }[] = [];
  async function capture(stage: string) {
    const tree = await accessibilityTree(session);
    captures.push({ stage, tree });
    return tree;
  }
  await page.getByRole('combobox', { name: expected.controls.size, exact: true }).focus();
  const controls = await capture('controls');
  expect(accessibilityNode(controls, 'combobox', expected.controls.size).properties.focused).toBe(
    true,
  );
  accessibilityNode(controls, 'button', expected.controls.newGame);
  await page.keyboard.press('Tab');
  expect(
    accessibilityNode(await capture('new-game-control'), 'button', expected.controls.newGame)
      .properties.focused,
  ).toBe(true);
  await page.keyboard.press('Tab');
  await page.keyboard.press('Tab');
  const closed = await capture('board-entry');
  for (const name of expected.closed) accessibilityNode(closed, 'button', name);
  expect(accessibilityNode(closed, 'button', expected.closed[0]).properties.focused).toBe(true);
  await page.getByRole('status').evaluate((element) => {
    const results: string[] = [];
    element.setAttribute('data-result-history', '[]');
    new MutationObserver(() => {
      results.push(element.textContent ?? '');
      element.setAttribute('data-result-history', JSON.stringify(results));
    }).observe(element, { childList: true, subtree: true, characterData: true });
  });
  for (const [turn, pair] of EXAMPLE_PAIRS.entries()) {
    await moveKeyboardTo(page, pair[0], expected.size);
    await page.keyboard.press('Enter');
    const revealed = await capture(`revealed-${turn + 1}`);
    expect(
      accessibilityNode(revealed, 'button', expected.revealed[pair[0]]).properties.focused,
    ).toBe(true);
    if (turn === 0) await page.clock.runFor(3000);
    await moveKeyboardTo(page, pair[1], expected.size);
    await page.keyboard.press('Space');
    const matched = await capture(`turn-${turn + 1}`);
    for (const index of pair)
      expect(
        accessibilityNode(matched, 'button', expected.matched[index]).properties.disabled,
      ).toBe(true);
    const result = accessibilityNode(matched, 'status');
    expect(result.properties.live).toBe('polite');
    expect(result.properties.atomic).toBe(true);
    expect(result.text).toBe(expected.turns[turn]);
  }
  const win = await capture('completed');
  expect(win.filter((node) => node.role === 'paragraph').map((node) => node.text)).toContain(
    expected.win,
  );
  const announcements: unknown = JSON.parse(
    (await page.getByRole('status').getAttribute('data-result-history')) ?? '[]',
  );
  expect(announcements).toEqual(expected.turns);
  await page.keyboard.press('Tab');
  expect(await page.locator('.card:focus').count()).toBe(0);
  const exit = await capture('board-exit');
  expect(
    accessibilityNode(exit, 'DisclosureTriangle', expected.controls.summary).properties.focused,
  ).toBe(true);
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Shift+Tab');
  await page.keyboard.press('Enter');
  const reset = await capture('new-game');
  expect(accessibilityNode(reset, 'button', expected.controls.newGame).properties.focused).toBe(
    true,
  );
  for (const name of expected.closed) accessibilityNode(reset, 'button', name);
  expect(accessibilityNode(reset, 'status').text).toBe(expected.newGame);
  await page.locator('summary').click();
  await page.getByRole('button', { name: 'Export snapshot', exact: true }).click();
  const snapshot = await page.getByLabel('Snapshot JSON', { exact: true }).inputValue();
  const loadEvents = [
    {
      stage: 'invalid-board',
      field: 'Board code',
      value: 'invalid',
      button: 'Load board',
      notice: 'Invalid board code.',
    },
    {
      stage: 'invalid-snapshot',
      field: 'Snapshot JSON',
      value: '{',
      button: 'Load snapshot',
      notice: 'Invalid snapshot.',
    },
    {
      stage: 'loaded-snapshot',
      field: 'Snapshot JSON',
      value: snapshot,
      button: 'Load snapshot',
      notice: 'Loaded snapshot. Select Resume to continue.',
    },
  ];
  for (const event of loadEvents) {
    await page.getByLabel(event.field, { exact: true }).fill(event.value);
    const button = page.getByRole('button', { name: event.button, exact: true });
    for (let repeat = 1; repeat <= 2; repeat += 1) {
      await button.click();
      await expect(button).toBeFocused();
      await expect(page.locator('.load-notice')).toHaveText(event.notice);
      const tree = await capture(`${event.stage}-${repeat}`);
      const status = accessibilityNode(tree, 'status');
      expect(tree.filter((node) => node.role === 'status')).toHaveLength(1);
      expect(status.properties.live).toBe('polite');
      expect(status.properties.atomic).toBe(true);
      expect(status.text).toBe(event.notice);
    }
  }
  await expect(page.getByRole('button', { name: 'Resume', exact: true })).toBeVisible();
  // A paused import blocks activation without marking its unmatched cards disabled.
  await expect(page.locator('.card[aria-disabled="true"]')).toHaveCount(0);
  expect(
    JSON.parse((await page.getByRole('status').getAttribute('data-result-history')) ?? '[]'),
  ).toEqual([
    ...expected.turns,
    expected.newGame,
    ...loadEvents.flatMap((event) => [event.notice, event.notice]),
  ]);
  const readme = await readFile(new URL('../README.md', import.meta.url), 'utf8');
  expect(readme.split(/\r?\n/)).toContain(expected.readmeRecord);
  const record =
    JSON.stringify(
      {
        schemaVersion: 1,
        status: 'tree-checked',
        chromium: browser.version(),
        playwright: await playwrightVersion(),
        screenReader: null,
        spokenReview: 'User acceptance. No spoken output was tested by the developer.',
        captures,
      },
      null,
      2,
    ) + '\n';
  expect(record).not.toMatch(
    /\b(?:file|https?):\/\/|[A-Za-z]:[\\/]|nodeId|frameId|backendDOMNodeId/,
  );
  await writeFile(artifacts.outputPath('accessibility-journey.json'), record);
  await session.detach();
}, {}, Scrollbars.hidden, TestTimeouts.long);

import { PNG } from 'pngjs';
import { expect, test } from './browser-test.ts';
import { FACE_COUNT } from '../src/game/board/face-design.ts';
import { ART_URL, loadFixedBoard } from './game-fixture.ts';
import type { Page } from '@playwright/test';
import assert from 'node:assert/strict';

test('the face sheet stays a face sheet without a session-harness branch', async ({ page }) => {
  await page.goto(ART_URL + '#session');
  await expect(page.locator('figure')).toHaveCount(128);
  await expect(page.locator('.board-viewport')).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Unmount game', exact: true })).toHaveCount(0);
});

function silhouette(png: Buffer): string {
  const image = PNG.sync.read(png);
  assert.equal(image.width, 44);
  assert.equal(image.height, 44);
  const pixels: string[] = [];
  for (let offset = 0; offset < image.data.length; offset += 4) {
    const red = image.data[offset];
    const green = image.data[offset + 1];
    const blue = image.data[offset + 2];
    assert.ok(red !== undefined && green !== undefined && blue !== undefined);
    pixels.push(red + green + blue > 128 * 3 ? '1' : '0');
  }
  return pixels.join('');
}

test('the actual 44px faces keep distinct geometry without color cues', async ({
  page,
}, artifacts) => {
  await page.setViewportSize({ width: 1200, height: 900 });
  await page.goto(ART_URL);
  await expect(page.locator('figure .card')).toHaveCount(FACE_COUNT);
  await page.screenshot({ path: artifacts.outputPath('face-sheet-color.png'), fullPage: true });
  await page.addStyleTag({ content: '.face-sheet { filter: grayscale(1); }' });
  await page.screenshot({ path: artifacts.outputPath('face-sheet-grayscale.png'), fullPage: true });
  await page.locator('figure svg').evaluateAll((elements) => {
    for (const element of elements) {
      const shape = element.querySelector('g');
      const marker = element.querySelector(':scope > circle');
      if (!shape || !marker) throw new Error('Missing face geometry.');
      if (shape.getAttribute('fill') !== 'none') shape.setAttribute('fill', '#F4F6FF');
      shape.setAttribute('stroke', '#F4F6FF');
      marker.setAttribute('fill', '#F4F6FF');
    }
  });
  const masks = [];
  for (const card of await page.locator('figure .card').all())
    masks.push(silhouette(await card.screenshot()));
  expect(new Set(masks).size).toBe(FACE_COUNT);
  await page.screenshot({ path: artifacts.outputPath('face-sheet-neutral.png'), fullPage: true });
});

test('the face marker keeps the specified surround and geometry', async ({ page }) => {
  await page.goto(ART_URL);
  const geometry = await page
    .locator('figure svg')
    .first()
    .evaluate((element) => {
      const marker = element.querySelector(':scope > circle');
      const shape = element.querySelector('g');
      if (!marker || !shape) throw new Error('Missing geometry.');
      return {
        viewBox: element.getAttribute('viewBox'),
        radius: marker.getAttribute('r'),
        stroke: marker.getAttribute('stroke-width'),
        background: getComputedStyle(marker).stroke,
      };
    });
  expect(geometry).toEqual({
    viewBox: '0 0 100 100',
    radius: '5',
    stroke: '3',
    background: 'rgb(17, 22, 37)',
  });
});

test('solid fills, outline strokes and marker fills share the face palette color', async ({
  page,
}) => {
  await page.goto(ART_URL);
  const colors = [
    '#63E7FF',
    '#FF71D6',
    '#8BEA7D',
    '#FFE082',
    '#FFB064',
    '#B49AFF',
    '#FF8296',
    '#D9F3FF',
  ];
  const actual = await page.locator('figure svg').evaluateAll((elements) =>
    elements.map((element) => ({
      fill: element.querySelector('g')?.getAttribute('fill'),
      stroke: element.querySelector('g')?.getAttribute('stroke'),
      marker: element.querySelector(':scope > circle')?.getAttribute('fill'),
    })),
  );
  expect(actual).toHaveLength(FACE_COUNT);
  for (const [id, face] of actual.entries()) {
    const color = colors[Math.floor(id / 8) % colors.length];
    expect(face).toEqual({ fill: id < 64 ? color : 'none', stroke: color, marker: color });
  }
});

// Card size, the grid it sits in and the board's custom properties depend on where a card is
// placed. Every other computed style must come from the card's own styles.
const PLACEMENT = new Set([
  'width',
  'height',
  'inline-size',
  'block-size',
  'min-width',
  'min-height',
  'min-inline-size',
  'min-block-size',
  'grid-template-columns',
  'grid-template-rows',
  'perspective-origin',
  'transform-origin',
]);

function revealedCardStyle(page: Page) {
  return page
    .locator('.card.revealed')
    .first()
    .evaluate(
      async (card, placement) => {
        // The hover border fades back over 120ms, so read the settled style.
        await Promise.all(card.getAnimations().map((animation) => animation.finished));
        const style = getComputedStyle(card);
        return Object.fromEntries(
          Array.from(style)
            .filter((name) => !name.startsWith('--') && !placement.includes(name))
            .map((name) => [name, style.getPropertyValue(name)]),
        );
      },
      [...PLACEMENT],
    );
}

test('the face sheet draws the same card as the game outside the control styles', async ({
  page,
}) => {
  await loadFixedBoard(page);
  await page.locator('.card').first().click();
  await page.mouse.move(0, 0);
  const game = await revealedCardStyle(page);
  await page.goto(ART_URL);
  expect(await revealedCardStyle(page), 'A07 card styles stay with the card').toEqual(game);
});
